1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/** Insurance values are independent of base premiums and of any premium modifier. */
68	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
69	  sword: 1000,
70	  amulet: 600,
71	  staff: 800,
72	  potion: 400,
73	  rune: 250,
74	  moonstone: 250,
75	};
76	
77	const DEDUCTIBLE_PER_DAMAGE = 100;
78	const CAP_MULTIPLIER = 2;
79	const CLAIM_HALVING_THRESHOLD = 8;
80	const CLAIM_HALVING_RATE = 0.5;
81	const FULLY_REIMBURSED_MATERIAL = "dragon";
82	
83	const COMPONENT_TYPES = ["rune", "moonstone"];
84	const BLOCK_SIZE = 3;
85	const BLOCK_BASE_PREMIUM = 60;
86	const CURSE_SURCHARGE_RATE = 0.5;
87	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
88	const HIGH_ENCHANTMENT_THRESHOLD = 5;
89	const LOYALTY_DISCOUNT_RATE = 0.2;
90	const LOYALTY_YEARS_THRESHOLD = 2;
91	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
92	
93	const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);
94	
95	/** Premiums round up — in the MHPCO's favour. */
96	const roundUpToWholeG = (amount: number): number => Math.ceil(amount);
97	
98	/** Payouts round down — also in the MHPCO's favour. */
99	const roundDownToWholeG = (amount: number): number => Math.floor(amount);
100	
101	const groupByType = (items: Item[]): Map<string, Item[]> => {
102	  const groups = new Map<string, Item[]>();
103	  for (const item of items) {
104	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
105	  }
106	  return groups;
107	};
108	
109	const basePremiumForItem = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
110	
111	/**
112	 * Components are priced per group of alike items, because a building block of
113	 * exactly 3 alike components earns a special rate. Main items price per item.
114	 */
115	const basePremiumForGroup = (type: string, group: Item[]): number => {
116	  if (COMPONENT_TYPES.includes(type) && group.length === BLOCK_SIZE) {
117	    return BLOCK_BASE_PREMIUM;
118	  }
119	  return sum(group.map(basePremiumForItem));
120	};
121	
122	/** Item-specific surcharges apply to the affected item's own base premium. */
123	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
124	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
125	  {
126	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
127	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
128	  },
129	];
130	
131	const itemSurchargeTotalFor = (item: Item): number =>
132	  sum(
133	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
134	      ({ rate }) => basePremiumForItem(item) * rate,
135	    ),
136	  );
137	
138	/**
139	 * Policy-wide modifiers are rates on the UNMODIFIED policy base premium — not
140	 * on the running total, and not on the item surcharges. Charging 10 % of a
141	 * cursed sword's 150 G rather than of its 100 G base is the mistake this
142	 * indirection exists to prevent.
143	 */
144	const policyModifierTotalFor = (policyBasePremium: number, rates: number[]): number =>
145	  sum(rates.map((rate) => policyBasePremium * rate));
146	
147	/**
148	 * Discounts are negative rates, so the policy modifiers stay a single sum.
149	 *
150	 * The initial assessment surcharge is deliberately NOT in here: it is charged on
151	 * every policy, including a long-standing customer's follow-up contract, so it
152	 * depends on nothing about the customer.
153	 */
154	const customerModifierRatesFor = (customer: Customer): number[] =>
155	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD ? [-LOYALTY_DISCOUNT_RATE] : [];
156	
157	/** The follow-up discount depends on scenario position, not on the customer. */
158	const policyModifierRatesFor = (customer: Customer, isFollowUpContract: boolean): number[] => [
159	  INITIAL_ASSESSMENT_SURCHARGE_RATE,
160	  ...customerModifierRatesFor(customer),
161	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_RATE] : []),
162	];
163	
164	/**
165	 * The customer and the contract's position in the scenario are context, not
166	 * subject: they are named at the call site so a bare `true` never has to be
167	 * decoded back into "this is a follow-up contract".
168	 */
169	interface PolicyContext {
170	  customer: Customer;
171	  isFollowUpContract: boolean;
172	}
173	
174	const quotePremium = (items: Item[], { customer, isFollowUpContract }: PolicyContext): number => {
175	  const policyBasePremium = sum(
176	    [...groupByType(items)].map(([type, group]) => basePremiumForGroup(type, group)),
177	  );
178	  const itemSurchargeTotal = sum(items.map(itemSurchargeTotalFor));
179	  const policyModifierTotal = policyModifierTotalFor(
180	    policyBasePremium,
181	    policyModifierRatesFor(customer, isFollowUpContract),
182	  );
183	  return roundUpToWholeG(
184	    policyBasePremium + itemSurchargeTotal + policyModifierTotal + PROCESSING_FEE,
185	  );
186	};
187	
188	/** A policy created by a quote step; claims draw down its remaining cap. */
189	interface Policy {
190	  items: Item[];
191	  remainingCap: number;
192	}
193	
194	const openPolicy = (items: Item[]): Policy => {
195	  const insuranceSum = sum(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
196	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
197	};
198	
199	/**
200	 * The reimbursed share depends on the damaged item. The 50 % high-enchantment
201	 * clause is checked before dragon material, so it wins when both would apply.
202	 */
203	const reimbursedShareOf = (damage: Damage, item: Item): number => {
204	  if ((item.enchantment ?? 0) >= CLAIM_HALVING_THRESHOLD) {
205	    return damage.amount * CLAIM_HALVING_RATE;
206	  }
207	  if (item.material === FULLY_REIMBURSED_MATERIAL) {
208	    return damage.amount;
209	  }
210	  return damage.amount;
211	};
212	
213	/** The deductible applies per damage event, after the clause. */
214	const reimbursementFor = (damage: Damage, items: Item[]): number => {
215	  const damagedItem = items.find((item) => item.type === damage.itemType)!;
216	  return reimbursedShareOf(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
217	};
218	
219	/**
220	 * Pure: returns the settlement WITHOUT drawing down the policy. The caller owns
221	 * the policy store and applies `remainingCap`, so a claim's effect on later
222	 * claims is visible at the call site rather than hidden in a shared reference.
223	 */
224	const settleClaim = (policy: Policy, incident: Incident): ClaimResult => {
225	  const claimed = sum(incident.damages.map((damage) => reimbursementFor(damage, policy.items)));
226	  const payout = roundDownToWholeG(Math.min(claimed, policy.remainingCap));
227	  return { payout, remainingCap: policy.remainingCap - payout };
228	};
229	
230	export const runScenario = (scenario: Scenario): ScenarioResult => {
231	  const results: StepResult[] = [];
232	  /** Keyed by step index, because that is what a claim's `policy` refers to. */
233	  const policiesByStepIndex = new Map<number, Policy>();
234	  let quotesSoFar = 0;
235	
236	  scenario.steps.forEach((step, stepIndex) => {
237	    if (step.op === "quote") {
238	      results.push({
239	        premium: quotePremium(step.items, {
240	          customer: scenario.customer,
241	          isFollowUpContract: quotesSoFar > 0,
242	        }),
243	      });
244	      quotesSoFar += 1;
245	      policiesByStepIndex.set(stepIndex, openPolicy(step.items));
246	      return;
247	    }
248	
249	    /**
250	     * `!` asserts the claim names a policy that exists. Nothing validates that
251	     * yet — a claim against an unknown step index throws an opaque TypeError.
252	     * The pending "claim references an item not part of the policy" test drives
253	     * out the real error mechanism; until it says what should happen, inventing
254	     * one here would be implementing ahead of the tests.
255	     */
256	    const policy = policiesByStepIndex.get(step.policy)!;
257	    const settlement = settleClaim(policy, step.incident);
258	    /** Successive claims draw down one shared cap. */
259	    policiesByStepIndex.set(step.policy, {
260	      ...policy,
261	      remainingCap: settlement.remainingCap,
262	    });
263	    results.push(settlement);
264	  });
265	
266	  return { results };
267	};
