/**
 * The reimbursed share depends on the damaged item. The 50 % high-enchantment
 * clause is checked before dragon material, so it wins when both would apply.
 */
const reimbursedShareOf = (damage: Damage, item: Item): number => {
  if ((item.enchantment ?? 0) >= CLAIM_HALVING_THRESHOLD) {
    return damage.amount * CLAIM_HALVING_RATE;
  }
  if (item.material === FULLY_REIMBURSED_MATERIAL) {
    return damage.amount;
  }
  return damage.amount;
};

/** The deductible applies per damage event, after the clause. */
const reimbursementFor = (damage: Damage, items: Item[]): number => {
  const damagedItem = items.find((item) => item.type === damage.itemType)!;
  return reimbursedShareOf(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
};

