/**
 * The deductible applies per damage event, after the clause.
 *
 * `!` asserts the damaged type is insured. Matching is by TYPE ONLY and does
 * not consume the matched item, so a policy with two swords resolves both
 * sword damages to the first one. The pending "two swords, two damage entries"
 * and "more damage entries than items insured → error" tests drive out
 * per-entry matching; until they say what should happen, inventing it here
 * would be implementing ahead of the tests.
 */
const reimbursementFor = (damage: Damage, items: Item[]): number => {
  const damagedItem = items.find((item) => item.type === damage.itemType)!;
  return coveredAmountFor(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
};

